"""Collection routes for the Vrbo and Booking.com pulls. Measured cells come from the run ledger, account balance, raw file timestamps and raw rows. Every other cell carries basis = estimated or not tested."""
import json,glob,os,pandas as pd,numpy as np
A=os.path.expanduser('~/Downloads/ABNB/'); R=A+'rival_overlap/'; O=A+'reverse_eng/'
L=pd.read_csv(R+'00_admin/run_ledger.csv'); F=L[L.phase=='FULL']
bk=F[F.actor=='booking-scraper']; vr=F[F.actor=='vrbo-scraper']; ls=vr[vr.rows.isin([390,494])]; dt=vr[~vr.index.isin(ls.index)]
MK=['san_diego','seattle','hawaii','lisbon']; bu=vu=0; br=vl=0
for m in MK:
    b=sum([json.load(open(x)) for x in glob.glob(R+f'01_raw/booking/{m}/*FULL*')],[]); v=sum([json.load(open(x)) for x in glob.glob(R+f'01_raw/vrbo/{m}/*LISTINGS*FULL*')],[])
    br+=len(b); bu+=len({x.get('hotelId') for x in b}); vl+=len(v); vu+=len({x.get('expediaPropertyId') for x in v if x.get('vrboId')})
assert br==bk.rows.sum() and vl==ls.rows.sum(),(br,bk.rows.sum(),vl,ls.rows.sum())
b_row=bk.usd.sum()/br; b_u=bk.usd.sum()/bu; l_row=ls.usd.sum()/vl; l_u=ls.usd.sum()/vu
settled=dt[dt.usd>1].iloc[0]; d_row=settled.usd/settled.rows
print('booking',br,bu,round(bk.usd.sum(),3),round(b_row,5),round(b_u,5)); print('vrbo list',vl,vu,round(ls.usd.sum(),3),round(l_row,5),round(l_u,5)); print('detail rows',dt.rows.sum(),'settled',settled.rows,settled.usd,round(d_row,6),'ledger usd',round(dt.usd.sum(),4))
led=L[L.phase.isin(['FULL','PILOT'])].usd.sum(); uns=(dt.rows.sum()-settled.rows)*d_row; pil=L[(L.phase=='PILOT')&(L.actor=='vrbo-scraper')&(L.usd<.01)].rows.sum()*d_row
print('ledger study',round(led,2),'unsettled full detail',round(uns,2),'pilot detail',round(pil,2),'sum',round(led+uns+pil,2),'balance 18.13 gap',round(18.13-led-uns-pil,2)); q=L[L.phase.str.startswith('quar')].usd.sum(); print('quarantine',round(q,2))
b_rpm=63.0; l_rpm=140.8; d_rpm=64.0
t_b=385/(bu/br)/b_rpm; t_v=385/(vu/vl)/l_rpm+385/d_rpm
HAND=2.0; OWN=243/36.73
rows=[]
def add(**k): rows.append(k)
M='measured'; E='estimated'; N='not tested'
