add(route='Apify',rival='Vrbo',tool='memo23/vrbo-scraper, listing step',cost_per_row_usd=round(l_row,5),cost_per_unique_row_usd=round(l_u,5),cost_basis=f'{M}: run ledger, 4 runs, ${ls.usd.sum():.2f}, {vl} rows, {vu} unique; store headline $0.10 per 1,000 understated this 26 times',rows_per_min=l_rpm,speed_basis=f'{M}: scrape timestamps, 132.4 to 147.0 a run at maxConcurrency 6',fields_returned=28,fields_basis=f'{M}: 27 of 28 filled on 90%+ of rows',licence_key='No, 0 of 200 rows checked',coordinates='Yes, 1,872 of 1,872',bedrooms='Yes, 1,690 of 1,872',failure_modes='283 duplicate rows (15.1%); San Diego stopped at 345 unique; no licence key, so the detail step is required',cost_385_rows_usd=round(385*l_u,2),cost_385_basis=f'{M} rate on unique rows',cost_4_markets_usd=round(4*385*l_u,2),minutes_385_rows=round(385/(vu/vl)/l_rpm,1),minutes_basis=f'{E}: measured rate scaled',hours_of_person_time_385=0.0)
add(route='Apify',rival='Vrbo',tool='one-api/vrbo-scraper, detail step',cost_per_row_usd=round(d_row,5),cost_per_unique_row_usd=round(d_row,5),cost_basis=f'{M}: one settled run, ${settled.usd:.4f} for {settled.rows} rows; the other 3 FULL runs show $0.0001 in the ledger because charges settled after the snapshot',rows_per_min=d_rpm,speed_basis=f'{M}: ledger start to save time, 58 to 68 a run, upper bound on duration',fields_returned=14,fields_basis=f'{M}: 13 of 14 filled on 90%+ of rows, key inside the Raw field',licence_key='Yes, parsed from Raw, 80.2% to 94.7% of rows by market',coordinates='Yes',bedrooms='In Raw',failure_modes='Ledger under-records spend until charges settle; saves only at the end of the run',cost_385_rows_usd=round(385*d_row,2),cost_385_basis=f'{M} rate',cost_4_markets_usd=round(4*385*d_row,2),minutes_385_rows=round(385/d_rpm,1),minutes_basis=f'{E}: measured rate scaled',hours_of_person_time_385=0.0)
add(route='Apify',rival='Vrbo',tool='listing plus detail, as run',cost_per_row_usd=None,cost_per_unique_row_usd=round(l_u+d_row,5),cost_basis=f'{M}: sum of the two steps',rows_per_min=round(385/t_v,1),speed_basis=f'{E}: 385 unique rows over the two steps run in sequence',fields_returned=42,fields_basis=f'{M}: 28 plus 14, some overlap',licence_key='Yes',coordinates='Yes',bedrooms='Yes',failure_modes='As the two steps above',cost_385_rows_usd=round(385*(l_u+d_row),2),cost_385_basis=f'{M} rates',cost_4_markets_usd=round(4*385*(l_u+d_row),2),minutes_385_rows=round(t_v,1),minutes_basis=f'{E}: measured rates scaled',hours_of_person_time_385=0.0)
