add(route='Apify, first pull discarded',rival='Vrbo, Booking.com, Expedia',tool='memo23, voyager and memo23 Expedia actors',cost_per_row_usd=round(q/qv.rows.sum(),5),cost_per_unique_row_usd=None,cost_basis=f'{M}: run ledger, {len(qv)} runs, ${q:.2f}, {int(qv.rows.sum())} rows, all quarantined',rows_per_min=None,speed_basis=N,fields_returned=None,fields_basis=N,licence_key='Not the design key at the time',coordinates='Yes',bedrooms='Partly',failure_modes='3 ABORTED runs; row counts set by scraper limits; Booking.com rows came nearest first; Expedia returned hotels only; no pilot gate before spend',cost_385_rows_usd=None,cost_385_basis='Not applicable',cost_4_markets_usd=None,minutes_385_rows=None,minutes_basis=N,hours_of_person_time_385=None)
